#include "p360_irq_arm_adapter.h"
static int permit(const struct p360_irq_arm_adapter_io*io,void*c){return io&&io->permit&&io->permit(c);}
static int rd(const struct p360_irq_arm_adapter_io*io,void*c,uint32_t o,uint32_t*v){if(!permit(io,c)||!io->read32||!v)return -1;return io->read32(c,o,v);}
static int wr(const struct p360_irq_arm_adapter_io*io,void*c,uint32_t o,uint32_t v){if(!permit(io,c)||!io->write32)return -1;if(io->write32(c,o,v))return -1;if(io->barrier)io->barrier(c);return 0;}
static int snapshot(const struct p360_irq_arm_adapter_io*io,void*c,struct p360_irq_arm_snapshot*s){if(!s)return -1;return rd(io,c,P360_DSP_ADSPIS,&s->adspis)||rd(io,c,P360_DSP_HIPCI,&s->hipci)||rd(io,c,P360_DSP_HIPCIE,&s->hipcie)||rd(io,c,P360_DSP_HIPCT,&s->hipct)||rd(io,c,P360_DSP_HIPCTE,&s->hipcte)||rd(io,c,P360_DSP_HIPCCTL,&s->hipcctl)||rd(io,c,P360_DSP_ADSPIC,&s->adspic);}
static int remask(const struct p360_irq_arm_adapter_io*io,void*c){uint32_t v;if(rd(io,c,P360_DSP_ADSPIC,&v)||wr(io,c,P360_DSP_ADSPIC,v&~P360_ADSPIC_IPC))return -1;if(rd(io,c,P360_DSP_HIPCCTL,&v)||wr(io,c,P360_DSP_HIPCCTL,v&~(P360_HIPCCTL_BUSY|P360_HIPCCTL_DONE)))return -1;if(rd(io,c,P360_DSP_ADSPIC,&v)||(v&P360_ADSPIC_IPC))return -1;if(rd(io,c,P360_DSP_HIPCCTL,&v)||(v&(P360_HIPCCTL_BUSY|P360_HIPCCTL_DONE)))return -1;return 0;}
int p360_irq_arm_adapter_run(const struct p360_irq_arm_adapter_io*io,void*context,uint64_t epoch,int accepting,unsigned queued,int poisoned,int fault,int mask_confirmed,struct p360_irq_arm_adapter_result*r){int status=P360_IRQ_ADAPTER_ARGUMENT;if(r){struct p360_irq_arm_adapter_result z={0};*r=z;}if(!io||!io->permit||!io->read32||!io->write32||!r)return status;if(!permit(io,context)){r->status=P360_IRQ_ADAPTER_ACCESS;return r->status;}if(snapshot(io,context,&r->before)){r->status=P360_IRQ_ADAPTER_SNAPSHOT;return r->status;}if(p360_irq_arm_prepare(&r->before,epoch,accepting,queued,poisoned,fault,mask_confirmed,&r->plan)){r->status=P360_IRQ_ADAPTER_POLICY;return r->status;}r->writes_started=1;if(wr(io,context,P360_DSP_HIPCCTL,r->plan.hipcctl_after)){status=P360_IRQ_ADAPTER_WRITE;goto fail;}{uint32_t v;if(rd(io,context,P360_DSP_HIPCCTL,&v)||v!=r->plan.hipcctl_after){status=P360_IRQ_ADAPTER_VERIFY;goto fail;}}if(wr(io,context,P360_DSP_ADSPIC,r->plan.adspic_after)){status=P360_IRQ_ADAPTER_WRITE;goto fail;}if(snapshot(io,context,&r->after)||p360_irq_arm_verify(&r->after,&r->plan)){status=P360_IRQ_ADAPTER_VERIFY;goto fail;}r->status=P360_IRQ_ADAPTER_OK;return 0;fail:r->poison_required=1;r->rollback_attempted=1;r->rollback_proved=remask(io,context)==0;r->status=r->rollback_proved?status:P360_IRQ_ADAPTER_ROLLBACK_UNPROVED;return r->status;}
